<section class="page-header"><div><span class="eyebrow">Pre-sales billing</span><h1>Estimates & Quotations</h1><p>Prepare priced proposals, record acceptance and convert approved work into invoices.</p></div><div class="page-actions"><?php if(can('invoices.create')):?><a class="button button-primary" href="<?= url('estimates/create') ?>"><i class="fa-solid fa-plus"></i> Create estimate</a><?php endif;?></div></section>
<section class="panel table-panel"><form class="filter-bar" method="get"><div class="search-control"><i class="fa-solid fa-magnifying-glass"></i><input name="q" value="<?= e($q) ?>" placeholder="Estimate number or client…"></div><label><span>Status</span><select name="status"><option value="">All statuses</option><?php foreach(['Draft','Sent','Accepted','Rejected','Expired','Converted'] as $s):?><option <?= $status===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach;?></select></label><button class="button button-secondary">Apply</button></form><div class="table-scroll"><table class="data-table"><thead><tr><th>Estimate</th><th>Client / project</th><th>Type</th><th>Date</th><th>Valid until</th><th>Total</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><a class="table-link" href="<?= url('estimates/'.$row['id']) ?>"><?= e($row['estimate_number']) ?></a></td><td><strong><?= e($row['company_name']) ?></strong><small class="cell-sub"><?= e($row['project_name']?:'General proposal') ?></small></td><td><?= e($row['estimate_type']) ?></td><td><?= e(date('d M Y',strtotime($row['estimate_date']))) ?></td><td><?= $row['valid_until']?e(date('d M Y',strtotime($row['valid_until']))):'—' ?></td><td><strong><?= money($row['grand_total']) ?></strong></td><td><span class="status-badge <?= status_class($row['status']) ?>"><?= e($row['status']) ?></span></td><td class="row-actions"><a class="icon-button" href="<?= url('estimates/'.$row['id']) ?>"><i class="fa-regular fa-eye"></i></a><a class="icon-button" href="<?= url('estimates/'.$row['id'].'/print?format=pdf') ?>"><i class="fa-solid fa-file-pdf"></i></a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8"><div class="empty-state"><span><i class="fa-solid fa-file-signature"></i></span><h3>No estimates found</h3><p>Create the first quotation or adjust the filters.</p></div></td></tr><?php endif;?></tbody></table></div></section>
